function envOr(name, fallback) {
  try { return ($env && $env[name]) || fallback; } catch (e) { return fallback; }
}

/* Provider. Anything speaking the OpenAI chat-completions protocol works here:
 * Groq, OpenRouter, OpenAI, or a local Ollama at
 * http://<host>:11434/v1/chat/completions. */
const C = {
  base: envOr('LLM_API_BASE', 'https://openrouter.ai/api/v1/chat/completions'),
  key: envOr('LLM_API_KEY', 'sk-or-v1-PASTE-YOUR-OPENROUTER-KEY'),
  model: envOr('LLM_MODEL', 'PASTE-YOUR-OPENROUTER-MODEL-ID')
};

const p = $json.body || $json;
if (!p.callback) { throw new Error('payload has no callback field'); }

/* Model per task. decompile is the hard one; a capability sentence is not. */
const TASK_MODELS = {
  decompile: envOr('LLM_MODEL_DECOMPILE', ''),
  bugs: envOr('LLM_MODEL_BUGS', ''),
  behaviour: envOr('LLM_MODEL_BEHAVIOUR', ''),
  'explain-finding': envOr('LLM_MODEL_EXPLAIN', '')
};
const taskModel = TASK_MODELS[p.task] || C.model;

/* OpenRouter serves the same model from several hosts and orders them by price
 * by default, which is often the busiest. Ask for the fastest instead. */
const isOpenRouter = String(C.base).indexOf('openrouter.ai') !== -1;
const providerSort = envOr('LLM_PROVIDER_SORT', isOpenRouter ? 'throughput' : '');

const fallbackModels = String(envOr('LLM_MODEL_FALLBACKS', ''))
  .split(',')
  .map(function (s) { return s.trim(); })
  .filter(Boolean);

const f = p.function || {};
const image = p.image || {};

const shownBlocks = [];

/* 999 meant 'never truncate', which pushed prompts from ~1,850 to ~7,800
 * tokens and put a single request at 85% of a 12,000/minute budget. 48
 * blocks covers most real functions whole while keeping the prompt inside
 * what a free tier will serve; raise it on a paid tier. */
const MAX_BLOCKS = Number(envOr('LLM_MAX_BLOCKS', 120));
const MAX_INSNS_PER_BLOCK = Number(envOr('LLM_MAX_INSNS', 999));
const MAX_ASM_LINES = Number(envOr('LLM_MAX_ASM_LINES', 2000));

/* Control-flow edges, rendered on the block header.
 *
 * The engine computes these and the payload has always carried them; the prompt
 * discarded them. Without edges the model reconstructs control flow by reading
 * jump targets out of operand strings - which works for a direct jump and fails
 * for anything else, and gives it no way to see that two branches reconverge.
 * C is structured and assembly is not, so this is the fact that most directly
 * decides whether the output is an if/else or a pile of gotos.
 *
 * `has_unresolved_exit` travels with it. A block with no successors is normally
 * a return; one with an unresolved exit is a jump table the analysis could not
 * follow, and the model must not describe it as a dead end. */
function blockHeader(b) {
  const edges = (b.successors || [])
    .filter(function (s) { return s && s.target; })
    .map(function (s) { return s.target + '(' + (s.kind || 'edge') + ')'; })
    .join(' ');
  return '//' + b.start
    + (edges ? ' -> ' + edges : '')
    + (b.has_unresolved_exit ? ' [unresolved exit: jump target not recovered]' : '');
}

const allBlocks = f.blocks || [];
const asm = [];
for (const b of allBlocks.slice(0, MAX_BLOCKS)) {
  if (!b.start) { continue; }
  shownBlocks.push(b.start);
  asm.push(blockHeader(b));
  const insns = b.instructions || [];
  for (const i of insns.slice(0, MAX_INSNS_PER_BLOCK)) {
    asm.push((i.va || '') + ':' + (i.mnemonic || 'db') + ' ' + (i.operands || ''));
  }
  if (insns.length > MAX_INSNS_PER_BLOCK) {
    asm.push('...+' + (insns.length - MAX_INSNS_PER_BLOCK));
  }
}
if (allBlocks.length > MAX_BLOCKS) {
  asm.push('...+' + (allBlocks.length - MAX_BLOCKS) + ' blocks');
}
if (asm.length > MAX_ASM_LINES) {
  asm.length = MAX_ASM_LINES;
  asm.push('...truncated');
}

const blockList = shownBlocks;

const callees = (p.callees || []).slice(0, 12).map(function (c) {
  const known = c.summary || ('(not lifted yet; imports ' + ((c.api_calls || []).join(', ') || 'none') + ')');
  return '- ' + (c.name || c.va) + ': ' + known;
}).join('\n');

/* The calling convention is a fixed property of the platform, not something
 * worth rediscovering from register traffic on every request. Stating it costs
 * one line and turns `mov rcx, rbx` into "argument 1 = rbx". */
const abi = image.arch === 'x86_64'
  ? 'abi: Microsoft x64 - RCX,RDX,R8,R9 are integer args 1-4, XMM0-3 float args, '
    + 'RAX returns, further args at [rsp+0x20], caller reserves 32 bytes shadow space'
  : 'abi: 32-bit - arguments on the stack unless the convention below says otherwise';

/* Frame layout. `local_size` bounds every stack buffer in the function, which is
 * the one number a bounds argument turns on. */
const frame = f.frame
  ? 'frame: locals=' + f.frame.local_size
    + ' saved_regs=' + f.frame.saved_regs_size
    + ' frame_pointer=' + (f.frame.uses_frame_pointer ? 'yes (rbp)' : 'no (rsp-relative)')
  : 'frame: not recovered';

const facts = [
  'fn:' + (f.name || f.va) + '@' + f.va,
  'arch:' + (image.arch || '?'),
  'convention:' + (f.convention || 'unknown'),
  abi,
  frame,
  'blocks:' + (f.block_count || 0) + ' insns:' + (f.instruction_count || 0),
  'cc:' + (f.cyclomatic_complexity || 0),
  'untrusted:' + (f.reachable_from_input ? 'y' : 'n'),
  'imports:' + ((f.api_calls || []).join(',') || 'none'),
  'strings:' + ((f.referenced_strings || []).join('|') || 'none'),
  'unreachable_blocks:' + ((f.unreachable_blocks || []).join(',') || 'none'),
  '',
  'callees:',
  callees || '(none)',
  '',
  'asm: block headers carry control-flow edges as  //<block> -> <target>(<kind>)',
  asm.join('\n')
].join('\n');

const RULES = 'Severity, reachability and call paths are derived by a static engine and are facts. '
  + 'Explain them; never re-rate them. Reply with one JSON object and nothing else: no prose, no '
  + 'markdown fences. NEVER use "..." or placeholder comments in the code field. Every assembly '
  + 'block shown must have a corresponding C translation.';

let schema, ask;

if (p.task === 'decompile') {
  schema = JSON.stringify({
    code: '<complete readable C for this function, real newlines, no placeholders>',
    summary: '<one sentence: what this function does>'
  });
  ask = 'Reconstruct readable C for this function. Translate EVERY assembly block shown into C.'
    + '\n\nUse the control-flow edges. Each block header is //<block> -> <target>(<kind>), where '
    + 'kind is fall-through, taken, jump, indirect-jump, call or return. Two branches meeting at a '
    + 'common successor is an if/else; an edge back to a dominating block is a loop. Recover those '
    + 'structures rather than emitting goto for every branch. A block marked [unresolved exit] has '
    + 'a jump whose target the analysis could not recover - say so in a comment; do not present it '
    + 'as a dead end or invent a destination.'
    + '\n\nUse the frame and convention lines. Stack slots below the frame pointer are locals: name '
    + 'them local_<offset> and size them against the stated locals total. Registers holding '
    + 'arguments on entry are arguments - name them accordingly rather than as raw registers.'
    + '\n\nPadding and data-only blocks may be rendered as a comment saying what they are. A jump '
    + 'table must NOT: reconstruct it as the control flow it implements, normally a switch, because '
    + 'replacing it with a comment deletes a branch structure while appearing thorough.'
    + '\n\nTag provenance on EVERY line. End each line of C with a comment //@ followed by the '
    + 'address of the assembly block that line came from. Repeat the address on every line, even '
    + 'when several lines in a row come from the same block - the tags are how coverage is measured, '
    + 'and a line without one is recorded as not translated. Every block listed below must appear on '
    + 'at least one line, including blocks that reduce to a single statement or a comment. Use only '
    + 'these block addresses, exactly as written: '
    + (blockList.join(', ') || '(none)')
    + '. Do not invent an address. The tags are stripped before the code is stored; they exist so '
    + 'the C can be lined up against the disassembly.';
} else if (p.task === 'bugs') {
  schema = JSON.stringify({
    issues: [{
      title: '<short title>',
      detail: '<why this is a defect>',
      engine_finding: '<exact api string from engine findings; omit when none applies>',
      confidence: 'high|medium|low'
    }]
  });
  ask = 'Identify defects in this function. The engine findings below are established facts. When '
    + 'your issue corresponds to one, set engine_finding to that exact api string; when the engine '
    + 'did not flag it, omit the field rather than inventing a value. Return an empty issues array '
    + 'if you find nothing.'
    + '\n\nThe frame line gives the total size of this function\'s locals. A copy into a stack '
    + 'buffer cannot exceed that total, so use it when arguing about bounds, and say when the '
    + 'destination size is not determinable rather than assuming one.'
    + '\n\nEngine findings:\n' + JSON.stringify(p.engine_findings || [], null, 1)
    + '\n\nCall path from the input source:\n' + JSON.stringify(p.call_path_context || [], null, 1);
} else if (p.task === 'behaviour') {
  schema = JSON.stringify({ summary: '<one or two sentences on the capability shown>' });
  ask = 'Describe the capability this function demonstrates. Describe ability, not intent: the '
    + 'same APIs appear in installers, updaters and backup tools as in malware.';
} else if (p.task === 'explain-finding') {
  schema = JSON.stringify({
    summary: '<what this code is doing>',
    why_severity: '<why the rating the engine gave is defensible>',
    impact: '<what an attacker could achieve>',
    remediation: '<what a fix looks like, as advice>',
    preconditions: ['<what the attacker still needs>'],
    confidence: 'high|medium|low'
  });
  ask = 'Explain this finding, which the engine has already rated. Do not output a severity field.'
    + '\n\nFinding:\n' + JSON.stringify(p.finding || {}, null, 1);
} else {
  throw new Error('unknown task: ' + p.task);
}

const systemText = 'You analyse one function of a Windows PE binary. ' + RULES
  + ' Required shape: ' + schema;
const userText = ask + '\n\n' + facts;
const promptChars = systemText.length + userText.length;

const outputTokens = p.task === 'decompile' ? 4096 : 2048;

return [{
  json: {
    provider_sort: providerSort || null,
    prompt_chars: promptChars,
    approx_tokens: Math.round(promptChars / 4),
    asm_lines: asm.length,
    blocks_shown: blockList.length,
    blocks_total: allBlocks.length,
    edges_shown: allBlocks.reduce(function (n, b) {
      return n + ((b.successors || []).length);
    }, 0),
    api_base: C.base,
    api_key: C.key,
    model: taskModel,
    task: p.task,
    callback: p.callback,
    blocks: blockList,
    request_body: Object.assign(
      {
        model: taskModel,
        temperature: 0.2,
        max_tokens: outputTokens
      },
      fallbackModels.length > 0
        ? { models: [taskModel].concat(fallbackModels) }
        : {},
      providerSort ? { provider: { sort: providerSort } } : {},
      String(envOr('LLM_JSON_MODE', '1')) === '0'
        ? {}
        : { response_format: { type: 'json_object' } },
      {
        messages: [
          { role: 'system', content: systemText },
          { role: 'user', content: userText }
        ]
      }
    )
  }
}];

const prep = $('Prepare').first().json;

/* Pull the //@<block> tags back out of the generated C.
 *
 * line_mapping is what links a line of C to a basic block, and therefore what
 * makes the decompiler, the disassembly and the graph one view instead of three
 * text boxes. Asking a model to emit the array directly does not work: it has to
 * count lines it has not written yet, and it invents plausible addresses. Asking
 * it to tag each line as it writes that line is a question it can answer, and
 * the array is then built here by counting - which is not a thing a model should
 * be doing anyway.
 *
 * Every address is checked against the real block list. A tag naming a block
 * that does not exist is dropped rather than stored: a mapping that points at
 * nothing would scroll the listing to the wrong place, and a wrong link is worse
 * than an absent one. */
function stripMarkers(codeText, validBlocks) {
  const valid = new Set(validBlocks || []);
  const lines = [];
  const mapping = [];
  /* `current` is the block being translated, not a one-shot. A marker line
   * opens a block and every line after it belongs to that block until the next
   * marker. Carrying it forward is what turns one cheap tag per block into a
   * mapping for every line. */
  let current = null;
  String(codeText).split('\n').forEach(function (raw) {
    const at = raw.lastIndexOf('//@');
    let text = raw;
    let address = null;
    if (at >= 0) {
      address = raw.slice(at + 3).trim();
      text = raw.slice(0, at).trimEnd();
    }
    /* A marker alone on its line labels the code that FOLLOWS it, not the blank
     * line it sits on. Models put the tag on its own line often enough that
     * treating it as a normal line was visibly wrong: every mapping pointed one
     * row above its statement, and the stripped remains left a blank row between
     * every line of C. Carry the address forward and drop the empty line. */
    // A marker alone on its line opens a block; it contributes no code.
    if (address !== null && text.trim() === '') {
      current = address;
      return;
    }
    lines.push(text);
    // A trailing tag also moves the cursor, so the older per-line style still
    // produces a correct mapping.
    if (address !== null) { current = address; }
    const owner = current;
    if (owner && (valid.size === 0 || valid.has(owner))) {
      // Numbered by emitted lines, not source lines: dropped marker lines would
      // otherwise shift every mapping after them.
      mapping.push({ line: lines.length, block: owner });
    }
  });
  return { code: lines.join('\n'), line_mapping: mapping };
}

let text = '';
try { text = $json.choices[0].message.content || ''; } catch (e) { text = ''; }
text = String(text).trim();

if (text.slice(0, 3) === '```') {
  text = text.replace(/^```[a-zA-Z]*\n?/, '').replace(/```\s*$/, '').trim();
}

let out = null;
try { out = JSON.parse(text); } catch (e) { out = null; }

/* Distinguish "the model answered with something unusable" from "the call never
 * succeeded". With onError=continueRegularOutput on the model node, a failed
 * call arrives here as an error object rather than a completion, and rate
 * limiting is by far the most common cause.
 *
 * Either way something MUST be posted back. If nothing is, the backend keeps
 * that function marked "sent", the batch never reaches done, and the automated
 * run sits at the same stage forever with no error to show for it. */
const noCompletion = !$json || !$json.choices;
const upstreamError = noCompletion && $json
  ? ($json.error && ($json.error.message || $json.error)) || $json.message || 'model call failed'
  : null;

/* What the provider actually said, kept so a failure can be diagnosed from the
 * stored result rather than re-run and guessed at. */
let finishReason = null;
let rawExcerpt = '';
try {
  const choice = ($json.choices || [])[0] || {};
  finishReason = choice.finish_reason || null;
  rawExcerpt = String(text || '').slice(0, 500);
} catch (e) { /* diagnostics must never be the thing that fails */ }

if (!out || typeof out !== 'object') {
  let why;
  if (upstreamError) {
    why = 'The model call did not succeed: ' + upstreamError;
  } else if (!rawExcerpt) {
    // Empty content with finish_reason "length" is the signature of a reasoning
    // model whose thinking consumed the whole max_tokens budget.
    why = finishReason === 'length'
      ? 'The model returned nothing and stopped at the output limit. If this is a '
        + 'reasoning model, its thinking consumed the whole max_tokens budget '
        + 'before any answer was produced - raise the limit or use a '
        + 'non-reasoning model.'
      : 'The model returned an empty reply.';
  } else if (finishReason === 'length') {
    why = 'The reply was cut off at the output limit, so it is not valid JSON. '
        + 'Raise max_tokens for this task.';
  } else {
    why = 'The model reply could not be parsed as JSON. It answered, but not in '
        + 'the requested shape.';
  }
  out = prep.task === 'bugs' ? { issues: [] } : { summary: why };
  out.finish_reason = finishReason;
  out.raw_excerpt = rawExcerpt;
  // The backend treats a result carrying this flag as NOT done, so re-running
  // the batch retries exactly these and leaves the good ones alone.
  out.parse_error = true;
  out.error = why;
}

out.model = prep.model;

/* Token usage, straight from the provider. Input size was measurable locally;
 * output size was not, and it is what generation time actually tracks. Storing
 * it turns "why is this slow" into a number rather than a theory. */
try {
  if ($json && $json.usage) {
    out.usage = {
      prompt_tokens: $json.usage.prompt_tokens || null,
      completion_tokens: $json.usage.completion_tokens || null
    };
  }
} catch (e) { /* usage is optional; never fail a result over it */ }

if (prep.task === 'decompile' && typeof out.code === 'string') {
  const split = stripMarkers(out.code, prep.blocks);
  out.code = split.code;
  // A model that returned the array itself is taken at its word; this only
  // fills the gap, which is the normal case.
  if (!Array.isArray(out.line_mapping) || out.line_mapping.length === 0) {
    out.line_mapping = split.line_mapping;
  }
}

if (prep.task === 'explain-finding' || prep.task === 'bugs') {
  delete out.severity;
  delete out.severity_source;
}

return [{ json: { callback: prep.callback, result: out } }];
